#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<int> bit;

    Fenwick(int n) {
        this->n = n;
        bit.assign(n + 1, 0);
    }

    void add(int i, int value) {
        for (; i <= n; i += i & -i)
            bit[i] += value;
    }

    int sumPrefix(int i) {
        int result = 0;
        for (; i > 0; i -= i & -i)
            result += bit[i];
        return result;
    }
};

int main() {
    vector<long long> a = {100, 5, 20};
    vector<long long> compressed = a;

    sort(compressed.begin(), compressed.end());
    compressed.erase(unique(compressed.begin(), compressed.end()), compressed.end());

    Fenwick fenwick(compressed.size());

    for (long long x : a) {
        int rank = lower_bound(compressed.begin(), compressed.end(), x) - compressed.begin() + 1;
        fenwick.add(rank, 1);

        cout << "value = " << x
             << ", rank = " << rank
             << ", count <= value = " << fenwick.sumPrefix(rank)
             << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Query {
    int type;
    long long x;
    long long value;
};

int main() {
    vector<Query> queries = {
        {1, 100, 5},
        {1, 5, 3},
        {2, 1000000000LL, 0}
    };

    vector<long long> coords;

    for (const Query& query : queries) {
        if (query.type == 1)
            coords.push_back(query.x);
        else
            coords.push_back(query.x);
    }

    sort(coords.begin(), coords.end());
    coords.erase(unique(coords.begin(), coords.end()), coords.end());

    for (Query& query : queries) {
        int rank = lower_bound(coords.begin(), coords.end(), query.x) - coords.begin();
        cout << query.x << " -> " << rank << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<pair<long long, long long>> points = {
        {100, 1000},
        {5, 20},
        {100, 20}
    };

    vector<long long> xs, ys;

    for (auto [x, y] : points) {
        xs.push_back(x);
        ys.push_back(y);
    }

    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());

    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());

    for (auto [x, y] : points) {
        int rankX = lower_bound(xs.begin(), xs.end(), x) - xs.begin();
        int rankY = lower_bound(ys.begin(), ys.end(), y) - ys.begin();

        cout << '(' << rankX << ", " << rankY << ")\n";
    }

    return 0;
}
